/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METCustTransListingUIBuilder</c> UI builder
/// </summary>
class METCustActivityStatementUIBuilder extends SrsReportDataContractUIBuilder
{
    METCustActivityStatementContract    contract;
    DialogField                         usePrintManagementField, salesTaxCodes, toDate, fromDate, associatedAccount, legalEntity, footerNote;
    container                           conContainer;

}

Method.Source:
    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Builds dialog fields
    /// </summary>
    public void build()
    {
        contract = this.dataContractObject() as METCustActivityStatementContract;

        fromDate                = this.addDialogField(methodStr(METCustActivityStatementContract, parmFromDate), contract);
        salesTaxCodes           = this.addDialogField(methodStr(METCustActivityStatementContract, parmSalesTaxCode), contract);
        associatedAccount       = this.addDialogField(methodStr(METCustActivityStatementContract, parmAccountNum), contract);
        footerNote              = this.addDialogField(methodStr(METCustActivityStatementContract, parmFooterNote), contract);
        toDate                  = this.addDialogField(methodStr(METCustActivityStatementContract, parmToDate), contract);        
        legalEntity             = this.addDialogField(methodStr(METCustActivityStatementContract, parmLegalEntity), contract);
        usePrintManagementField = this.addDialogField(methodStr(METCustActivityStatementContract, parmUsePrintManagement), contract);
        
        
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Maps dialog fields above to contract method
    /// </summary>
    public void postBuild()
    {
        super();

        contract = this.dataContractObject() as METCustActivityStatementContract;

        toDate                  = this.bindInfo().getDialogField(contract, methodStr(METCustActivityStatementContract, parmToDate));
        salesTaxCodes           = this.bindInfo().getDialogField(contract, methodStr(METCustActivityStatementContract, parmSalesTaxCode));
        fromDate                = this.bindInfo().getDialogField(contract, methodStr(METCustActivityStatementContract, parmFromDate));
        usePrintManagementField = this.bindInfo().getDialogField(contract, methodStr(METCustActivityStatementContract, parmUsePrintManagement));
        associatedAccount       = this.bindInfo().getDialogField(contract, methodStr(METCustActivityStatementContract, parmAccountNum));
        legalEntity             = this.bindInfo().getDialogField(contract, methodStr(METCustActivityStatementContract, parmLegalEntity));
        footerNote              = this.bindInfo().getDialogField(contract, methodStr(METCustActivityStatementContract, parmFooterNote));

        salesTaxCodes.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METCustActivityStatementUIBuilder, fieldLookup), this);
        associatedAccount.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METCustActivityStatementUIBuilder, accountLookup), this);
        legalEntity.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METCustActivityStatementUIBuilder, legalEntityLookup), this);
     
    }

    /// <summary>
    /// Associated account num lookup
    /// </summary>
    /// <param name = "parmFormStringControl">formcontrol</param>
    public void accountLookup(FormStringControl parmFormStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    custTableQBDS;
        
        // MPJ-17526 Changed the datasource to CustTable - Start
        custTableQBDS = query.addDataSource(tableNum(CustTable));
        custTableQBDS.addSelectionField(fieldNum(CustTable, AccountNum));

        custTableQBDS.addOrderByField(fieldnum(CustTable, AccountNum));
        custTableQBDS.orderMode(OrderMode::GroupBy);
        // MPJ-17526 Changed the datasource to CustTable - End

        SysLookupMultiSelectGrid::lookup(query,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         conContainer);
    }

    /// <summary>
    /// LE lookup in metcustaccount
    /// </summary>
    /// <param name = "parmFormStringControl">form string control </param>
    public void legalEntityLookup(FormStringControl parmFormStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    companyInfoQBDS;

        // MPJ-17526 Changed the datasource to CompanyInfo - Start
        companyInfoQBDS =   query.addDataSource(tableNum(CompanyInfo));
        companyInfoQBDS.addSelectionField(fieldNum(CompanyInfo, DataArea));
       
        // MPJ-17526 Changed the datasource to CompanyInfo - End

        SysLookupMultiSelectGrid::lookup(query,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         conContainer);
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// SalesTaxCode lookup
    /// </summary>
    /// <param name = "parmFormStringControl">dialog field</param>
    public void fieldLookup(FormStringControl parmFormStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    tableQBDS;

        tableQBDS =   query.addDataSource(tableNum(TaxTable));

        tableQBDS.addSelectionField(fieldNum(TaxTable, TaxCode));
        tableQBDS.addSelectionField(fieldNum(TaxTable, TaxName));

        SysLookupMultiSelectGrid::lookup(query,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         conContainer);
    }

